import{_ as a,o,c as t,a2 as n}from"./chunks/framework.CHeM0PsO.js";const h=JSON.parse('{"title":"网易云合伙人-自动任务","description":"","frontmatter":{},"headers":[],"relativePath":"projects/lotus-plugin/docs/features/netease-partner.md","filePath":"projects/lotus-plugin/docs/features/netease-partner.md"}'),s={name:"projects/lotus-plugin/docs/features/netease-partner.md"};function c(d,e,r,p,l,i){return o(),t("div",null,[...e[0]||(e[0]=[n(`<h1 id="网易云合伙人-自动任务" tabindex="-1">网易云合伙人-自动任务 <a class="header-anchor" href="#网易云合伙人-自动任务" aria-label="Permalink to &quot;网易云合伙人-自动任务&quot;">​</a></h1><p>返回：<a href="./../README.html">文档目录</a> / <a href="./README.html">小功能索引</a></p><h2 id="初始化与登录" tabindex="-1">初始化与登录 <a class="header-anchor" href="#初始化与登录" aria-label="Permalink to &quot;初始化与登录&quot;">​</a></h2><p>仅机器人主人可操作，按顺序发送：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#初始化TuneWeave</span></span>
<span class="line"><span>#TuneWeave状态</span></span>
<span class="line"><span>#合伙人登录</span></span>
<span class="line"><span>#合伙人测试</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p><code>#合伙人测试</code> 会实际提交评分和配置的乐评，也接受 <code>#合伙人测试（执行）</code>。<code>#合伙人日志</code> 以合并转发查看当天日志中的歌曲、主分、各子项分数、对应乐评及每轮结果。</p><p>初始化独立下载适合当前系统的 TuneWeave 官方预编译文件，校验 SHA-256 后启动本机服务；已有可用实例直接复用。它不随工具环境初始化自动下载。初始化完成后，Yunzai 重启会恢复本机服务。默认地址为 <code>http://127.0.0.1:7832</code>，可通过 <code>tuneweave.api_url</code> 指向其他自托管实例；远程实例须自行部署。缺少所需登录或扩展 API 能力时会明确报错。当前发布物支持 Linux x64、Windows x64/arm64、macOS x64/arm64，其他平台需自行部署。</p><p>使用网易云音乐 App 扫码，账号凭据由 TuneWeave 服务端托管；Lotus 的 <code>data/netease/accounts.yaml</code> 仅保存账户别名、UID 和任务偏好。首次初始化本机服务时，使用 TuneWeave 官方启动 Cookie 配置承接第一个旧账号；该启动凭据只保存在私有 <code>data/tuneweave/bootstrap.json</code> 中。首次任务核验默认账号 UID 后，Lotus 账号文件移除旧 Cookie。多个旧账号中的其余账号、外部实例或身份不一致的账号须重新扫码，旧记录会保留。</p><h2 id="评分与汇报" tabindex="-1">评分与汇报 <a class="header-anchor" href="#评分与汇报" aria-label="Permalink to &quot;评分与汇报&quot;">​</a></h2><p>任务读取、额外任务读取和评分提交全部通过 TuneWeave 的网易云扩展 API。每首作品读取自己的 <code>supportExtraEvaTypes</code>（旧数据兼容 <code>dimensions</code>），每个子项独立打分；<code>extraScore</code> 会完整提交，不能仅发评论与主分。作品没有提供子项时，报告明确标注，不补造评分维度。</p><p>每个账号每日目标 20 首，完成数不足 20 时再重试一轮；两轮按作品 ID 合并，已完成作品不重复提交，最终只汇报一次。图片仅显示成功、失败数量；日志记录歌曲、主分、全部子项分数、对应乐评和每轮结果。已完成作品计入成功数。登录成功后启用自动任务，仍按 <code>netease_partner.schedule</code> 每日执行；默认每天 00:05，已有自定义 cron 保留。<code>notify_master: true</code> 时，自动任务给主人发送汇报图。启动补跑由 <code>auto_catch_up</code> 控制；手动与定时任务并发时只执行一轮。</p><p>乐评使用本机 <code>config/global.yaml</code> 的 <code>netease_partner.comments</code>，更新不会覆盖此文件；本机乐评库不纳入源码仓库。每轮优先不重复抽取，用完才循环，日志记录每首作品实际提交的乐评；账号关闭评论时明确标注未发布。</p><p>自动任务按日去重：当天执行过后，重复 cron 触发不再执行或汇报；失败重试已包含在同一次任务中。手动 <code>#合伙人测试</code> 仍可显式执行。</p><h2 id="数据与配置" tabindex="-1">数据与配置 <a class="header-anchor" href="#数据与配置" aria-label="Permalink to &quot;数据与配置&quot;">​</a></h2><ul><li><code>tuneweave.api_url</code>：自托管服务地址。</li><li><code>tuneweave.request_timeout_ms</code>：请求超时，默认 30000 毫秒。</li><li><code>netease_partner</code>：保留定时、通知、登录超时、操作间隔和评论配置；原 <code>api_url</code> 已移除。</li><li><code>data/tuneweave/</code>：本机可执行文件、私有账户数据与日志。</li><li><code>data/netease/accounts.yaml</code>：Lotus 账号信息；<code>data/netease/state.yaml</code>：任务状态。</li><li><code>data/logs/nep-latest.json</code>：当天最新的逐作品评分报告，次日执行覆盖；旧的带时间戳合伙人日志会清理，其他功能日志保留。</li></ul><p>账户数据和旧配置备份含有秘密，不应上传。</p>`,16)])])}const m=a(s,[["render",c]]);export{h as __pageData,m as default};
